import React from 'react';
import { FileText, GitBranch, ShieldCheck, Cpu, RefreshCw } from 'lucide-react';

const AiAgentsBar = () => {
  const agents = [
    {
      name: 'Resume Agent',
      icon: FileText,
      status: 'ACTIVE SCANNING',
      color: 'text-gold-300',
      bg: 'bg-bronze-800/50 border-bronze-100/30',
      indicatorBg: 'bg-gold-300'
    },
    {
      name: 'GitHub Agent',
      icon: GitBranch,
      status: 'SYNCHRONIZING',
      color: 'text-bronze-100',
      bg: 'bg-bronze-800/50 border-bronze-100/30',
      indicatorBg: 'bg-bronze-100'
    },
    {
      name: 'Verification Engine',
      icon: ShieldCheck,
      status: 'ONLINE',
      color: 'text-gold-400',
      bg: 'bg-bronze-800/50 border-bronze-100/30',
      indicatorBg: 'bg-gold-400'
    },
    {
      name: 'Trust Engine',
      icon: Cpu,
      status: 'READY',
      color: 'text-bronze-200',
      bg: 'bg-bronze-800/50 border-bronze-100/30',
      indicatorBg: 'bg-bronze-200'
    },
    {
      name: 'SkillSwap Engine',
      icon: RefreshCw,
      status: 'ACTIVE PAIRING',
      color: 'text-gold-300',
      bg: 'bg-bronze-800/50 border-bronze-100/30',
      indicatorBg: 'bg-gold-300'
    }
  ];

  return (
    <div className="w-full max-w-7xl mx-auto px-4 my-8">
      <div className="glass-card rounded-2xl p-4 border border-bronze-100/20 shadow-2xl backdrop-blur-2xl">
        <div className="flex items-center justify-between mb-3 px-2">
          <div className="flex items-center space-x-2">
            <span className="h-2 w-2 rounded-full bg-gold-300 animate-ping"></span>
            <h3 className="text-xs font-mono font-semibold tracking-wider text-bronze-100 uppercase">
              Autonomous AI Agent Grid
            </h3>
          </div>
          <span className="text-[11px] font-mono text-gold-300/90">
            5 / 5 AGENTS OPERATIONAL
          </span>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
          {agents.map((agent, index) => {
            const Icon = agent.icon;
            return (
              <div
                key={index}
                className={`p-3 rounded-xl border ${agent.bg} flex items-center space-x-3 transition-all duration-300 hover:scale-[1.02]`}
              >
                <div className={`p-2 rounded-lg bg-bronze-950/80 border border-bronze-100/20 ${agent.color}`}>
                  <Icon className="w-4 h-4" />
                </div>
                <div className="overflow-hidden">
                  <p className="text-xs font-heading font-semibold text-bronze-100 truncate">
                    {agent.name}
                  </p>
                  <div className="flex items-center space-x-1.5 mt-0.5">
                    <span className={`h-1.5 w-1.5 rounded-full ${agent.indicatorBg} animate-pulse`} />
                    <span className={`text-[10px] font-mono font-medium tracking-tight ${agent.color}`}>
                      {agent.status}
                    </span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default AiAgentsBar;
